const U=Deno.env.get('SUPABASE_URL')||'';
const S=Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')||'';
const K=Deno.env.get('SUPABASE_PUBLISHABLE_KEY')||Deno.env.get('SUPABASE_ANON_KEY')||'';
const TENANT_RE=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const GATEWAY_MIN=100000;
type TenantCtx={tenant_id:string;tenant_slug:string;business_name:string;merchant_name:string;public_origin:string;admin_origin:string;kds_origin:string;enabled:boolean};
const bootstrapMemo=new Map<string,{body:string,at:number}>();
async function tenantContext(req:Request):Promise<TenantCtx>{
  const raw=String(req.headers.get('x-sdb-tenant-id')||'').trim();
  const tenantId=TENANT_RE.test(raw)?raw:null;
  if(!S)throw new Error('tenant_service_unavailable');
  const r=await fetch(U+'/rest/v1/rpc/master_prototype_runtime_context',{
    method:'POST',
    headers:{apikey:S,Authorization:'Bearer '+S,'Content-Type':'application/json'},
    body:JSON.stringify({p_tenant_id:tenantId,p_origin:null,p_app_kind:'admin'}),
    cache:'no-store'
  });
  if(!r.ok)throw new Error('tenant_context_'+r.status);
  const j=await r.json();
  if(!j?.ok||j?.enabled===false)throw new Error('tenant_unavailable');
  return j as TenantCtx;
}
async function bootstrapBody(ctx:TenantCtx){
  const memo=bootstrapMemo.get(ctx.tenant_id);
  if(memo&&Date.now()-memo.at<15000)return memo.body;
  const r=await fetch(U+'/rest/v1/tenant_site_settings_public_v1?select=design_system&tenant_id=eq.'+encodeURIComponent(ctx.tenant_id)+'&limit=1',{
    headers:{apikey:S,Authorization:'Bearer '+S,'x-sdb-tenant-id':ctx.tenant_id},
    cache:'no-store'
  });
  if(!r.ok)throw new Error('bootstrap_fetch_'+r.status);
  const rows=await r.json();
  const row=rows&&rows[0]||{};
  const body=JSON.stringify([{...row,kds_url:ctx.kds_origin,tenant_id:ctx.tenant_id}]);
  bootstrapMemo.set(ctx.tenant_id,{body,at:Date.now()});
  return body;
}
